from torchvision.datasets import MNIST  # pyright: ignore
from datasig.algo import UID, KeyedShaMinHash
from datasig.dataset import TorchVisionDataset, IterableDataset
import cProfile
import argparse
import pstats
from abc import ABC, abstractmethod


class FingerprintProfile(ABC):
    """Abtract class for profiling dataset fingerprinting on a given dataset"""

    def __init__(self, nb_signatures: int = 400):
        self.profile = cProfile.Profile()
        self.dataset: IterableDataset

    @abstractmethod
    def _setup(self) -> None:
        """Method that needs to be overridden by child classes to set self.dataset"""
        pass

    def _run_profile(
        self, uid: bool = True, fingerprint: bool = True, profile_canonization: bool = True
    ):
        if profile_canonization:
            self.profile.enable()

        if uid:
            uid_alg = UID(self.dataset)

        if fingerprint:
            fingerprint_alg = KeyedShaMinHash(self.dataset)

        if not profile_canonization:
            self.profile.enable()

        if uid:
            _ = uid_alg.digest()  # pyright: ignore
        if fingerprint:
            _ = fingerprint_alg.digest()  # pyright: ignore

        self.profile.disable()

    def __call__(
        self,
        profile_canonization: bool = True,
        profile_uid: bool = True,
        profile_fingerprint: bool = True,
    ) -> cProfile.Profile:
        self._setup()
        self._run_profile(
            uid=profile_uid,
            fingerprint=profile_fingerprint,
            profile_canonization=profile_canonization,
        )
        return self.profile


class TorchMNISTV0(FingerprintProfile):
    def _setup(self):
        train_data = MNIST(root="/tmp/mnist_data", train=True, download=True)
        self.dataset = TorchVisionDataset(train_data)  # pyright: ignore


def print_profile(profile: cProfile.Profile):
    sortby = pstats.SortKey.TIME
    ps = pstats.Stats(profile).sort_stats(sortby)
    ps.print_stats()


def main(args: argparse.Namespace):
    # Keys are (Target, datasig config version)
    target_map = {
        ("torch_mnist", "0"): TorchMNISTV0,
    }

    for target in args.targets:
        profile = target_map[(target, args.version)]()(
            profile_canonization=args.canonical,
            profile_uid=args.uid,
            profile_fingerprint=args.fingerprint,
        )
        print(f"#### Pofile for {target} - datasig v{args.version}\n")
        print_profile(profile)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("targets", nargs="*")
    parser.add_argument(
        "--canonical", action="store_true", help="Include dataset canonization in stats"
    )
    parser.add_argument("--uid", action="store_true", help="Include UID computation in stats")
    parser.add_argument(
        "--fingerprint", action="store_true", help="Include fingerprint computation in stats"
    )
    parser.add_argument(
        "--full",
        action="store_true",
        help="Include all canonization, UID, and fingerprint computation in stats",
    )
    parser.add_argument(
        "-v", "--version", default="0", help="Datasig config version to use. Defaults to v0"
    )
    args = parser.parse_args()
    if args.full:
        args.canonical = True
        args.uid = True
        args.fingerprint = True

    main(args)

import math
from abc import ABC, abstractmethod
import datasketch  # pyright: ignore[reportMissingTypeStubs]


class DatasetUID(bytes):
    def __new__(cls, data: bytes = b""):
        if len(data) != 32:
            raise ValueError("Dataset UID must be a valid SHA256 hash. Length is invalid.")

        return super().__new__(cls, data)


# Astract fingerprint class
class DatasetFingerprint(ABC):
    @abstractmethod
    def __len__(self) -> int:
        """Return information about the size of the fingerprint. The meaning
        of the size depends on the fingerprint method."""
        pass

    @abstractmethod
    def similarity(self, other: "DatasetFingerprint") -> float:
        """Return the dataset similary estimate between the datasets that this
        fingerprint and the other fingerprint correspond to."""
        pass

    @abstractmethod
    def comparison_accuracy(self) -> float:
        """Return the accuracy that this fingerprint has when compared to another fingerprint
        to approximate the Jaccard distance between two canonical datasets"""
        pass

    @abstractmethod
    def signature(self) -> bytes:
        pass


class BasicDatasetFingerprint(DatasetFingerprint):
    """A basic dataset fingerprint that stores the minhash signatures
    as a raw list of bytes"""

    def __init__(self, signatures: list[bytes]) -> None:
        self._signatures = signatures

    def __len__(self) -> int:
        return len(self._signatures)

    def similarity(self, other: "DatasetFingerprint") -> float:
        assert len(self) == len(other)
        assert isinstance(other, BasicDatasetFingerprint)
        # Count how many signature pairs are made of identical signatures
        return sum(map(lambda x: x[0] == x[1], zip(self._signatures, other._signatures))) / len(
            self
        )

    def comparison_accuracy(self) -> float:
        if self._signatures:
            return 1.0 - (1.0 / math.sqrt(len(self._signatures)))
        return 0.0

    def signature(self) -> bytes:
        return b"".join(self._signatures)


class DatasketchFingerprint(DatasetFingerprint):
    """A fingerprint that stores a minhash object from the
    datasketch library"""

    def __init__(self, minhash: datasketch.MinHash):
        self.minhash = minhash

    def __len__(self):
        return len(self.minhash)

    def similarity(self, other: "DatasetFingerprint"):
        assert isinstance(other, DatasketchFingerprint)
        return self.minhash.jaccard(other.minhash)

    def comparison_accuracy(self) -> float:
        # TODO(boyan): make sure using the length of the minhash
        # is correct for estimating the accuracy here
        l = len(self.minhash)
        if l:
            return 1.0 - (1.0 / math.sqrt(l))
        return 0.0

    def signature(self) -> bytes:
        return self.minhash.digest().tobytes()

from collections.abc import Iterable
from abc import ABC, abstractmethod
import hashlib
import struct
from itertools import groupby, islice
import numpy as np
import datasketch  # pyright: ignore[reportMissingTypeStubs]
from .fingerprint import (
    DatasetFingerprint,
    DatasetUID,
    BasicDatasetFingerprint,
    DatasketchFingerprint,
)
from typing import Self


class Algorithm(ABC):
    @abstractmethod
    def update(self, data: bytes | Iterable[bytes]) -> None:
        pass

    @abstractmethod
    def digest(self) -> DatasetFingerprint | DatasetUID:
        pass

    @abstractmethod
    def __str__(self) -> str:
        pass

    @abstractmethod
    def clone_config(self) -> Self:
        pass


class MinHash(Algorithm, ABC):
    def __init__(self, data: Iterable[bytes]):
        self._hashes: list[bytes] = []
        self._synced: bool = True
        self._fingerprint: DatasetFingerprint | None = None

        for d in data:
            self.update(d)

    def _sort(self):
        self._hashes.sort()

    def update(self, data: bytes | Iterable[bytes]) -> None:
        self._synced = False
        if isinstance(data, bytes):
            self._hashes.append(hashlib.sha256(data).digest())
        else:
            self._hashes += [hashlib.sha256(x).digest() for x in data if isinstance(x, bytes)]

    @abstractmethod
    def _get_fingerprint(self) -> DatasetFingerprint:
        pass

    def digest(self) -> DatasetFingerprint:
        if not self._synced or self._fingerprint is None:
            if not self._synced:
                self._hashes.sort()
            self._fingerprint = self._get_fingerprint()

        return self._fingerprint


class KeyedShaMinHash(MinHash):
    """Generate dataset fingerprints using the keyed SHA method.

    The figerprint is computed using the MinHash scheme.
    Random permutations are approximated by keyed SHA256 functions i.e. random bytes are appended to the input of SHA256.

    See https://web.eecs.utk.edu/~jplank/plank/classes/cs494/494/notes/Min-Hash/index.html, Min Hash with k hash functions.
    """

    lsh_magic_numbers: list[bytes] = [struct.pack(">I", i) for i in list(range(1, 401))]

    def __init__(self, data: Iterable[bytes] = [], nb_signatures: int = 400):
        super().__init__(data)
        self.nb_signatures = nb_signatures

    def __str__(self) -> str:
        return f"KeyedShaMinHash(nb_signatures={self.nb_signatures})"

    def clone_config(self) -> Self:
        return self.__class__(nb_signatures=self.nb_signatures)

    def _get_fingerprint(self) -> DatasetFingerprint:
        if len(self._hashes) < self.nb_signatures:
            raise ValueError(
                f"Not enough data points to compute a fingerprint: we need at least {self.nb_signatures} data points."
            )

        res: list[bytes | None] = [None] * 400
        for i in range(self.nb_signatures):
            for h in self._hashes:
                h2 = hashlib.sha256(h + KeyedShaMinHash.lsh_magic_numbers[i]).digest()
                if res[i] is None or res[i] > h2:  # pyright: ignore[reportOptionalOperand]
                    res[i] = h2

        return BasicDatasetFingerprint(res)  # pyright: ignore[reportArgumentType]


def gen_xor_magic_numbers() -> list[bytes]:
    """Deterministically generate 400 random magic numbers"""
    # Use a fixed seed and separate rng to ensure each run of
    # the function returns the SAME magic numbers
    rng = np.random.default_rng(0)
    return [rng.bytes(32) for _ in range(400)]


class XorMinHash(MinHash):
    """Generate dataset fingerprint based on XOR permutations.

    The figerprint is computed using the MinHash scheme.
    Random permutations are approximated by the output of SHA256 XORed with random 256 bits values.
    """

    xor_magic_numbers: list[bytes] = gen_xor_magic_numbers()

    def __init__(self, data: Iterable[bytes] = [], nb_signatures: int = 400):
        super().__init__(data)
        self.nb_signatures = nb_signatures

    def __str__(self) -> str:
        return f"XorMinHash(nb_signatures={self.nb_signatures})"

    def clone_config(self) -> Self:
        return self.__class__(nb_signatures=self.nb_signatures)

    def _get_fingerprint(self) -> DatasetFingerprint:
        if len(self._hashes) < self.nb_signatures:
            raise ValueError(
                f"Not enough data points to compute a fingerprint: we need at least {self.nb_signatures} data points."
            )

        res: list[bytes | None] = [None] * self.nb_signatures
        for i in range(self.nb_signatures):
            for h in self._hashes:
                h2 = bytes([a ^ b for a, b in zip(h, XorMinHash.xor_magic_numbers[i])])
                if res[i] is None or res[i] > h2:  # pyright: ignore[reportOptionalOperand]
                    res[i] = h2

        return BasicDatasetFingerprint(res)  # pyright: ignore[reportArgumentType]


class SingleShaMinHash(MinHash):
    """Generate dataset fingerprint based on a single SHA permutation

    The figerprint is computed using the MinHash scheme with a single permutation approximated by SHA256.
    Each distinct data point hash occupies at most one bottom-k slot.

    See https://web.eecs.utk.edu/~jplank/plank/classes/cs494/494/notes/Min-Hash/index.html, Min Hash with one hash functions.
    And https://en.wikipedia.org/wiki/MinHash#Variant_with_a_single_hash_function.
    """

    def __init__(self, data: Iterable[bytes] = [], nb_signatures: int = 400):
        super().__init__(data)
        self.nb_signatures = nb_signatures

    def __str__(self) -> str:
        return f"SingleShaMinHash(nb_signatures={self.nb_signatures})"

    def clone_config(self) -> Self:
        return self.__class__(nb_signatures=self.nb_signatures)

    def _get_fingerprint(self) -> DatasetFingerprint:
        # Sampling observations before deduplication lets repeated points
        # displace distinct points from the bottom-k set sketch.
        # MinHash.digest() has already sorted the hashes.
        distinct_hashes = list(
            islice((digest for digest, _ in groupby(self._hashes)), self.nb_signatures)
        )
        if len(distinct_hashes) < self.nb_signatures:
            raise ValueError(
                f"Not enough distinct data points to compute a fingerprint: we need at least {self.nb_signatures} distinct data points."
            )
        return BasicDatasetFingerprint(distinct_hashes)


class DatasketchMinHash(MinHash):
    """Generate dataset fingerprint based on universal hashing permutations

    The figerprint is computed using the MinHash scheme.
    Random permutations are approximated by universal hashing.

    See https://ekzhu.com/datasketch/minhash.html.
    We can customize this further using different hash functions and
    number of permutations.
    """

    def __init__(self, data: Iterable[bytes] = [], nb_signatures: int = 400):
        super().__init__(data)
        self.nb_signatures = nb_signatures

    def __str__(self) -> str:
        return f"DatasketchMinHash(nb_signatures={self.nb_signatures})"

    def clone_config(self) -> Self:
        return self.__class__(nb_signatures=self.nb_signatures)

    def _get_fingerprint(self) -> DatasetFingerprint:
        res = datasketch.MinHash(num_perm=self.nb_signatures)
        for d in self._hashes:
            res.update(d)  # pyright: ignore[reportUnknownMemberType]

        return DatasketchFingerprint(res)  # pyright: ignore[reportArgumentType]


class UID(Algorithm):
    """Generate dataset unique identifier"""

    def __init__(self, data: Iterable[bytes] = []) -> None:
        self._uid = hashlib.sha256()
        for h in data:
            self._uid.update(h)

    def __str__(self) -> str:
        return f"UID"

    def clone_config(self) -> Self:
        return self.__class__()

    def update(self, data: bytes | Iterable[bytes]) -> None:
        if isinstance(data, bytes):
            self._uid.update(data)
        else:
            for h in data:
                assert isinstance(h, bytes)
                self._uid.update(h)

    def digest(self) -> DatasetUID:
        # Hash the concatenation of the data points
        return DatasetUID(self._uid.digest())

