    def gen():
        i = 0
        while True:
            try:
                yield data[2 * i]
                i += 1
            except:
                break

    return gen()


def offset(data, offset):
    def gen():
        i = 0
        while True:
            try:
                yield data[i + offset]
                i += 1
            except:
                break

    return gen()


